style:
.wwu-link{transition:background 150ms ease,transform 150ms ease}
.wwu-link:hover{background:#fff !important;transform:translateX(3px)}
.wip-row{transition:border-color 150ms ease,transform 150ms ease}
.wip-row:hover{border-color:var(--artblue) !important;transform:translateX(3px)}
.wip-spin g{transform-origin:24px 24px;transform-box:view-box;animation:wipspin 4s linear infinite}
@keyframes wipspin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.wip-spin g{animation:none}}
